import {coastProgress} from './coast-progress.js?v=0.3.0';
import {categories,symbols,escapeHtml as esc,validPoint,tripKm,aggregate,parseGPX,exportGPX,number,today,validateEntry} from './core.js?v=0.3.0';
import {appendCoastalPoint,removeCoastalPoint,coastalPath,coastalSource} from './coastal.js?v=0.3.0';
import {getClient,loadEntries,saveEntry,signedPhoto,uploadPhoto} from './backend.js?v=0.3.0';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let entries=[],user=null,map,base,groups={},draft=null,drawLayer,locationLayer,mode=null,tab='mapa',loading=false,saving=false,practice=null,undoEntry=null,toastTimer,undoTimer,weatherRequest=0,importQueue=[];
const visible=e=>!e.deleted_at;const active=kind=>entries.filter(e=>visible(e)&&e.kind===kind);const draftKey=()=>`paleando:0.1:draft:${user?.id||'guest'}`;
function state(text){$('#save-state').textContent=text;}
function toast(message,undo=false){clearTimeout(toastTimer);$('#toast span').textContent=message;$('#toast').hidden=false;$('#undo').hidden=!undo;if(!undo&&undoEntry)$('#undo').hidden=false;if(!undo&&!undoEntry)toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
function openDialog(id){const d=$(id);if(!d.open)d.showModal();d.setAttribute('aria-label',d.querySelector('h2')?.textContent||'Paleando Menorca');}
function content(title,html){photoRequest++;weatherRequest++;$('#content-title').textContent=title;$('#content-body').innerHTML=html;openDialog('#content-dialog');}
function errorText(e){return e?.message||'No se pudo completar la operación. Inténtalo de nuevo.';}
function closeDialogs(){ $$('dialog[open]').forEach(d=>d.close());$('#menu-button').setAttribute('aria-expanded','false');}
function switchTab(name){if(practice&&!['mapa','diario'].includes(name))return;tab=name;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));$$('.view').forEach(v=>v.hidden=v.id!==`view-${name}`);if(name==='mapa')setTimeout(()=>map?.invalidateSize(),60);if(name==='diario')renderDiary();if(name==='progreso')renderProgress();}
function requireAccount(){if(practice)return true;if(!user){closeDialogs();openDialog('#auth-dialog');return false;}if(loading){toast('Espera a que termine la carga del diario.');return false;}return true;}
let syncVersion=0,accountEpoch=0,loginGuidePending=false,loadedAccount=null;
async function sync(){if(!user||saving||practice)return;const expectedUser=user.id,version=++syncVersion;loading=true;state('Cargando tu diario…');try{const data=await loadEntries();if(user?.id!==expectedUser||version!==syncVersion)return;loadedAccount=expectedUser;entries=data;state('Guardado en tu cuenta');render();return true;}catch(e){state('Error al cargar · pulsa Actualizar');toast(errorText(e));}finally{if(version===syncVersion)loading=false;}}
async function persist(entry){validateEntry(entry);if(practice){const saved={...structuredClone(entry),revision:(entry.revision||0)+1};const i=entries.findIndex(e=>e.id===entry.id);if(i<0)entries.unshift(saved);else entries[i]=saved;return saved;}if(!user)throw Error('Inicia sesión para guardar.');const owner=user.id,epoch=accountEpoch;state('Guardando…');try{const saved=await saveEntry(entry,owner);if(user?.id!==owner||epoch!==accountEpoch)throw Error('La sesión ha cambiado. Vuelve a abrir tu borrador en la cuenta original.');const i=entries.findIndex(e=>e.id===saved.id);if(i<0)entries.unshift(saved);else entries[i]=saved;state('Guardado en tu cuenta');return saved;}catch(e){if(epoch===accountEpoch)state(navigator.onLine?'Error de guardado · conserva tu borrador':'Pendiente de conexión · reintenta Guardar');throw e;}}
function stashDraft(){if(practice){$('#resume-draft').hidden=!draft;return true;}try{if(draft)localStorage.setItem(draftKey(),JSON.stringify(draft));else localStorage.removeItem(draftKey());$('#continue-draft').hidden=!draft;$('#resume-draft').hidden=!draft;return true;}catch{toast('No se ha podido conservar el borrador. Mantén esta pantalla abierta.');return false;}}
function recoverDraft(){try{const saved=JSON.parse(localStorage.getItem(draftKey())||'null');draft=saved&&['trip','plan'].includes(saved.kind)&&saved.data&&Array.isArray(saved.data.points)&&saved.data.points.every(validPoint)?saved:null;if(draft){draft.data.markers||=[];draft.data.photos||=[];}}catch{draft=null;}$('#continue-draft').hidden=!draft;}
function newEntry(kind='trip'){if(!requireAccount())return;if(draft){toast('Tienes un borrador. Continúa editándolo o descártalo desde la ficha.');showEditor();return;}draft={id:crypto.randomUUID(),kind,title:'',data:{date:today(),points:[],source:'manual',roundtrip:false,markers:[],photos:[]}};stashDraft();closeDialogs();beginDraw();}
function readForm(){if(!draft)return;const f=$('#entry-form');for(const name of ['date','duration','rating','wind','sea','notes','access'])draft.data[name]=f.elements[name].value;draft.title=f.elements.title.value;draft.data.roundtrip=f.elements.roundtrip.checked;draft.data.favorite=f.elements.favorite.checked;stashDraft();}
function showEditor(){if(!draft)return;mode=null;$('#draw-bar').hidden=true;$('#map-hint').hidden=true;closeDialogs();const f=$('#entry-form');f.reset();f.elements.id.value=draft.id;f.elements.title.value=draft.title;for(const name of ['date','duration','rating','wind','sea','notes','access'])f.elements[name].value=draft.data[name]||'';f.elements.roundtrip.checked=!!draft.data.roundtrip;f.elements.favorite.checked=!!draft.data.favorite;$('#editor-type').textContent=practice?'SALIDA DE PRÁCTICA':draft.kind==='plan'?'RUTA PENDIENTE':draft.revision?'EDITAR SALIDA':'NUEVA SALIDA';$('#save-entry').textContent=draft.kind==='plan'?'Guardar ruta pendiente':practice?'Guardar en la práctica':'Guardar salida';$('#editor-message').textContent='';$('#photo-input').disabled=false;renderDraft();openDialog('#editor-dialog');}
function renderDraft(){if(!draft)return;$('#route-summary').textContent=draft.data.points.length>=2?`${number(tripKm(draft.data))} km · ${draft.data.points.length} puntos${draft.data.source==='gpx'?' · GPX completo':draft.data.source==='coastal'?' · siguiendo la costa':''}${draft.data.snapMetres>25?' · ajuste a costa '+Math.round(draft.data.snapMetres)+' m':''}`:'Selecciona al menos dos puntos en el mapa';$('#draft-markers').innerHTML=(draft.data.markers||[]).map(m=>`<div class="route-summary"><span>${symbols[m.category]} ${esc(m.title)}</span><select aria-label="Fotografía de ${esc(m.title)}" data-marker-photo="${esc(m.id)}"><option value="">Sin fotografía</option>${(draft.data.photos||[]).map(p=>`<option value="${esc(p.id)}" ${m.photoId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button type="button" class="text-button danger" data-remove-marker="${esc(m.id)}">Quitar</button></div>`).join('')||'<p class="muted">Accesos, aparcamientos y rincones que recordar.</p>';$('#draft-photos').innerHTML=(draft.data.photos||[]).map(p=>`<figure><button type="button" class="text-button" data-photo="${esc(p.path||'example')}" data-photo-name="${esc(p.name)}">▧ ${esc(p.name)}</button><button type="button" data-remove-photo="${esc(p.id)}" class="text-button danger">Quitar de la galería</button></figure>`).join('');hydratePhotos($('#draft-photos'));drawDraft();}
function beginDraw(marker=false){if(!marker&&draft?.data.source==='gpx'){if(!confirm('¿Sustituir el trazado GPX por una ruta costera nueva?'))return;draft.data={...draft.data,points:[],anchors:[],source:'coastal'};stashDraft();}if(!marker&&draft?.data.source==='manual'&&draft.data.points.length>=2){try{const anchors=structuredClone(draft.data.points);draft.data={...draft.data,...coastalPath(anchors),anchors,source:'coastal'};stashDraft();}catch(error){toast(errorText(error));}}if(!map){toast('El mapa no ha cargado. Reintenta al recuperar la conexión.');return;}closeDialogs();switchTab('mapa');mode=marker?'marker':'route';$('#draw-bar').hidden=false;$('#draw-label').textContent=marker?'Toca dónde añadir el marcador':draft.data.points.length?'Añade un punto de paso junto a la costa':'Toca salida y llegada junto a la costa';$('#finish-draw').hidden=marker;$('#remove-point').hidden=marker;$('#map-hint').textContent=marker?'Un toque coloca el marcador; el recorrido no cambia.':'Marca salida y llegada. El trazado seguirá la costa; puedes añadir puntos de paso.';$('#map-hint').hidden=false;$('#map-wrap').scrollIntoView({behavior:'smooth',block:'center'});drawDraft();if(marker)guideAdvance('marker-start');}
function initMap(){if(!globalThis.L){$('.map-loading').textContent='No se pudo cargar el mapa. Comprueba la conexión y vuelve a abrir la página.';return;}$('#map').innerHTML='';map=L.map('map',{zoomControl:false}).setView([39.98,4.08],10);map.attributionControl?.addAttribution('Costa: IDEIB · GOIB / SITIBSA · MTIB 2012');setBase('terrain');for(const key of ['trips','plans',...Object.keys(categories)])groups[key]=L.layerGroup().addTo(map);drawLayer=L.layerGroup().addTo(map);locationLayer=L.layerGroup().addTo(map);map.on('click',e=>{if(!draft||!mode)return;if(mode==='marker'){if(practice)practice.markerPoint=[e.latlng.lat,e.latlng.lng];mode=null;$('#draw-bar').hidden=true;$('#map-hint').hidden=true;markerForm([e.latlng.lat,e.latlng.lng],true);guideAdvance('marker-point');return;}try{draft.data=appendCoastalPoint(draft.data,[e.latlng.lat,e.latlng.lng]);}catch(error){toast(errorText(error));return;}stashDraft();drawDraft();$('#draw-label').textContent=draft.data.points.length<2?'Salida marcada · toca la llegada':`${number(tripKm(draft.data))} km por la costa · ${draft.data.points.length} puntos${draft.data.snapMetres>25?' · ajuste '+Math.round(draft.data.snapMetres)+' m':''}`;if(practice&&draft.data.points.length>=2&&tripKm(draft.data)>.01)guideAdvance('points');});map.on('moveend',()=>{if(!practice)return;});let tileErrors=0;map.on('baselayerchange',()=>tileErrors=0);map._tileError=()=>{if(++tileErrors===3)toast('No se está cargando la cartografía. Comprueba la conexión o cambia la base en Capas.');};}
function setBase(value){if(!map)return;if(base)map.removeLayer(base);if(value==='satellite')base=L.tileLayer.wms('https://www.ign.es/wms-inspire/pnoa-ma',{layers:'OI.OrthoimageCoverage',format:'image/jpeg',attribution:'Ortofoto © IGN · PNOA',maxZoom:20});else if(value==='streets')base=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19});else base=L.tileLayer('https://tile.opentopomap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap · <a href="https://opentopomap.org">OpenTopoMap</a> (CC-BY-SA)',maxZoom:17});base.on('tileerror',()=>map._tileError?.());base.addTo(map);}
function drawDraft(){if(!drawLayer)return;drawLayer.clearLayers();if(!draft)return;const points=draft.data.points;if(points.length){L.polyline(points,{color:draft.data.roundtrip?'#ad5c28':'#11796f',weight:5,dashArray:'8 6'}).addTo(drawLayer);[points[0],...(points.length>1?[points.at(-1)]:[])].forEach(p=>L.marker(p,{interactive:false,icon:L.divIcon({className:'route-point',iconSize:[16,16]})}).addTo(drawLayer));}}
function renderMap(){if(!map)return;Object.values(groups).forEach(g=>g.clearLayers());for(const e of entries.filter(visible)){if(['trip','plan'].includes(e.kind)&&e.data.points?.length>1){const line=L.polyline(e.data.points,{color:e.kind==='plan'?'#6d8399':e.data.roundtrip?'#ad5c28':'#11796f',weight:4,opacity:.85,dashArray:e.kind==='plan'?'6 6':null}).addTo(groups[e.kind==='trip'?'trips':'plans']);line.on('click',ev=>{if(mode)return;L.DomEvent.stopPropagation(ev);detail(e.id);});if(e.kind==='trip')for(const m of e.data.markers||[])addMarker(m,e.id);}if(e.kind==='place')addMarker({...e.data,id:e.id,title:e.title});}drawDraft();}
function addMarker(m,routeId){if(!validPoint(m.point)||!groups[m.category])return;const marker=L.marker(m.point,{bubblingMouseEvents:true,icon:L.divIcon({className:'',html:`<div class="place-pin">${symbols[m.category]}</div>`,iconSize:[32,32],iconAnchor:[16,16]})}).addTo(groups[m.category]);marker.on('click',ev=>{if(mode)return;L.DomEvent.stopPropagation(ev);if(routeId)detail(routeId);else placeDetail(m.id);});marker.bindTooltip(esc(m.title));}
function render(){const realEntries=practice?practice.entries:entries;const a=aggregate(realEntries),c=coastProgress(realEntries);$('#total-km').textContent=number(a.km);$('#trip-count').textContent=a.count?`${a.count} ${a.count===1?'salida guardada':'salidas guardadas'}`:'Sin salidas todavía';$('#coast-total').textContent=number(c.totalKm);$('#coast-covered').textContent=number(c.coveredKm);$('#energy').style.width=`${c.percent}%`;$('.energy-track').setAttribute('aria-valuenow',c.percent.toFixed(4));$('.energy-track').setAttribute('aria-valuetext',`${number(c.coveredKm)} de ${number(c.totalKm)} kilómetros de costa recorridos, ${number(c.percent)} por ciento`);$('#goal-copy').textContent=`Costa pendiente: ${number(c.pendingKm)} km`;$('#goal-percent').textContent=c.percent>0&&c.percent<.01?'< 0,01 %':`${number(c.percent)} %`;const notes=[];if(c.unmatched)notes.push(`${c.unmatched} ${c.unmatched===1?'recorrido sin coincidencia costera':'recorridos sin coincidencia costera'}`);if(c.gps)notes.push('Cobertura GPX estimada');$('#coast-status').textContent=notes.join(' · ');$('#coast-status').hidden=!notes.length;$('#account-button').textContent=user?'Mi cuenta ↗':'Entrar ↗';$('#logout').hidden=!user;$('#continue-draft').hidden=!draft;$('#resume-draft').hidden=!draft;renderMap();renderDiary();if(tab==='progreso')renderProgress();}
function coastInfo(){const c=coastProgress(practice?practice.entries:entries);content('Tu costa, sin contar dos veces',`<p><strong>${number(c.totalKm)} km</strong> de costa de referencia, calculados desde la geometría principal conectada que utiliza la app.</p><p>Las salidas realizadas cubren los tramos por los que has pasado. La unión de esos tramos cuenta cada parte una sola vez, aunque repitas salida o regreses por el mismo sitio.</p><p>Los kilómetros paleados sí incluyen todas las repeticiones y la vuelta. Las rutas pendientes y las salidas eliminadas no suman.</p><h3>Recorridos GPX</h3><p>Su distancia paleada conserva el recorrido original. Su cobertura de costa es una estimación: solo se acreditan tramos paralelos a la huella GPS y a menos de 75 m. No se unen automáticamente sus extremos bordeando calas que el GPX no recorre.</p><h3>Cartografía de referencia</h3><p><a href="${coastalSource.url}" target="_blank" rel="noopener">${coastalSource.name}</a>. Geometría simplificada a 2,5 m. Esta longitud depende de la escala y de la geometría utilizada; no es una longitud oficial universal ni incluye todos los islotes.</p>`);}

function empty(title,copy,action='new'){return `<div class="empty-state"><div class="empty-icon">⌁</div><h3>${title}</h3><p>${copy}</p>${action?`<button class="button primary" data-action="${action}">${action==='new'?'＋ Guardar mi primera salida':action==='new-place'?'＋ Añadir lugar':'＋ Planificar ruta'}</button>`:''}</div>`;}
function entryCard(e){return `<article class="card"><div class="card-top"><span>${esc(e.data.date||'Sin fecha')}</span><span>${e.data.favorite?'★ Favorita':e.kind==='plan'?'POR DESCUBRIR':'SALIDA'}</span></div><h3>${esc(e.title)}</h3><div class="card-stat">${number(tripKm(e.data))} <small>km</small></div><p>${esc((e.data.notes||'Un recuerdo más en tu cuaderno de mar.').slice(0,110))}</p><div class="actions"><button class="text-button" data-action="detail" data-id="${e.id}">Ver aventura ↗</button><button class="text-button" data-action="edit" data-id="${e.id}">Editar</button></div></article>`;}
function renderDiary(){const selected=$('#year-filter').value;const years=[...new Set(active('trip').map(e=>e.data.date?.slice(0,4)).filter(Boolean))].sort().reverse();$('#year-filter').innerHTML='<option value="">Todos los años</option>'+years.map(y=>`<option ${selected===y?'selected':''}>${y}</option>`).join('');const q=$('#trip-search').value.toLocaleLowerCase('es');const list=active('trip').filter(e=>(!selected||e.data.date?.startsWith(selected))&&(!$('#favorites-filter').checked||e.data.favorite)&&`${e.title} ${e.data.notes||''}`.toLocaleLowerCase('es').includes(q)).sort((a,b)=>String(b.data.date||'').localeCompare(String(a.data.date||'')));$('#trip-list').innerHTML=list.map(entryCard).join('')||empty(active('trip').length?'Sin resultados':'Aquí empieza tu historia',active('trip').length?'Prueba con otro filtro.':'Todavía no hay salidas. Tu próxima aventura tiene sitio aquí.',active('trip').length?'':'new');}
function renderProgress(){const realEntries=practice?practice.entries:entries,year=String(new Date().getFullYear()),a=aggregate(realEntries,year),all=aggregate(realEntries),c=coastProgress(realEntries),max=Math.max(1,...a.months),months=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];$('#progress-content').innerHTML=`<div class="progress-cards coast-progress-cards"><div class="card"><span>Costa total</span><strong>${number(c.totalKm)} km</strong></div><div class="card"><span>Costa recorrida · sin repetir</span><strong>${number(c.coveredKm)} km</strong></div><div class="card"><span>Costa pendiente</span><strong>${number(c.pendingKm)} km</strong></div><div class="card"><span>Distancia paleada · todas las salidas</span><strong>${number(all.km)} km</strong></div></div><button class="text-button" data-action="coast-info">Cómo se calcula la costa ⓘ</button><div class="card"><h3>Tu año en el agua · ${year}</h3><p class="muted">${a.count} salidas · ${number(a.km)} km paleados · ${number(a.minutes/60)} h registradas</p>${months.map((m,i)=>`<div class="month-row"><span>${m}</span><div class="month-bar"><i style="width:${a.months[i]/max*100}%"></i></div><span>${number(a.months[i])} km</span></div>`).join('')}</div><button class="text-button" data-action="goal">＋ Mi objetivo anual de kilómetros</button>`;}

function edit(id){if(!requireAccount())return;const e=entries.find(e=>e.id===id);if(!e)return;if(draft&&draft.id!==id){toast('Resuelve el borrador abierto antes de editar otra salida.');showEditor();return;}draft=structuredClone(e);if(practice)practice.beforeEdit=JSON.stringify(draft);stashDraft();showEditor();guideAdvance('edit');}
function detail(id){const e=entries.find(e=>e.id===id);if(!e)return;content(e.title,`<span class="badge">${e.kind==='plan'?'RUTA PENDIENTE':'SALIDA'} · ${esc(e.data.date)}</span><h3>${number(tripKm(e.data))} km ${e.data.roundtrip?'· Ida y vuelta':''}</h3><dl class="detail-dl"><dt>Duración real</dt><dd>${esc(e.data.duration||'—')} min</dd><dt>Acceso al mar</dt><dd>${esc(({easy:'Fácil',medium:'Con precaución',hard:'Difícil'})[e.data.access]||'Sin registrar')}</dd><dt>Viento observado</dt><dd>${esc(e.data.wind||'Sin registrar')}</dd><dt>Estado del mar</dt><dd>${esc(e.data.sea||'Sin registrar')}</dd><dt>Valoración</dt><dd>${e.data.rating?'★'.repeat(Math.max(0,Math.min(5,Number(e.data.rating)||0))):'Sin valorar'}</dd></dl><p style="white-space:pre-wrap">${esc(e.data.notes||'Sin notas')}</p><h3>Marcadores</h3>${(e.data.markers||[]).map(m=>`<p>${symbols[m.category]} ${esc(m.title)} · ${esc(categories[m.category])}${m.photoId?` <button class="text-button" data-action="marker-photo" data-id="${e.id}" data-marker="${esc(m.id)}">Ver foto</button>`:''}</p>`).join('')||'<p class="muted">Sin marcadores</p>'}<div class="photo-grid">${(e.data.photos||[]).map(p=>`<button class="text-button" data-photo="${esc(p.path||'example')}" data-photo-name="${esc(p.name)}">▧ ${esc(p.name)}</button>`).join('')}</div><div class="actions"><button class="button primary" data-action="edit" data-id="${e.id}">Editar</button> <button class="text-button" data-action="locate" data-id="${e.id}">Ver en mapa</button> <button class="text-button" data-action="export" data-id="${e.id}">Exportar GPX</button> ${e.kind==='plan'?`<button class="text-button" data-action="complete" data-id="${e.id}">Registrar como realizada</button>`:''}<button class="text-button danger" data-action="delete" data-id="${e.id}">Eliminar</button></div>`);hydratePhotos($('#content-body'));guideAdvance('detail');}
async function deleteEntry(id){if(saving)return;if(undoEntry){toast('Primero deshaz la eliminación anterior o espera a que termine su plazo.',true);return;}const e=entries.find(e=>e.id===id);if(!e)return;if(draft){toast('Resuelve el borrador abierto antes de eliminar elementos.');return;}if(!confirm(`¿Eliminar «${e.title}»? Dejará de aparecer y se recalculará el progreso. Las fotografías no se borrarán del almacenamiento. Puedes deshacer durante 30 segundos.`))return;saving=true;try{const saved=await persist({...e,deleted_at:new Date().toISOString()});undoEntry={id:saved.id,until:Date.now()+30000};closeDialogs();render();toast(`«${e.title}» eliminado.`,true);clearTimeout(undoTimer);undoTimer=practice?null:setTimeout(()=>{undoEntry=null;$('#toast').hidden=true;},30000);guideAdvance('delete');}catch(e){toast(errorText(e));}finally{saving=false;}}
async function undo(){if(!undoEntry||saving)return;if(!practice&&Date.now()>undoEntry.until){undoEntry=null;toast('Ha terminado el plazo de recuperación.');return;}saving=true;try{const e=entries.find(e=>e.id===undoEntry.id);await persist({...e,deleted_at:null});undoEntry=null;clearTimeout(undoTimer);render();toast('Aventura recuperada.');guideAdvance('undo');}catch(e){toast(errorText(e),true);}finally{saving=false;}}
function showPlans(){guideAdvance('plans');closeDialogs();content('Aventuras por venir',`<p class="muted">Las rutas pendientes no suman kilómetros realizados.</p><button class="button primary" data-action="plan">＋ Planificar ruta</button><div class="card-grid" style="margin-top:20px">${active('plan').map(entryCard).join('')||empty('Un mar de posibilidades','Prepara una ruta y guárdala para otro día.','plan')}</div>`);}
function markerForm(point,route=false,existing=null){content(existing?'Editar lugar':route?'Un detalle para recordar':'Nuevo lugar',`<form id="place-form"><label>Nombre<input name="title" maxlength="180" required value="${esc(existing?.title||'')}" placeholder="Acceso junto al embarcadero"></label><label>Categoría<select name="category">${Object.entries(categories).map(([k,v])=>`<option value="${k}" ${existing?.data.category===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="form-row"><label>Latitud<input name="lat" type="number" step="any" min="-90" max="90" required value="${point?.[0]??''}"></label><label>Longitud<input name="lng" type="number" step="any" min="-180" max="180" required value="${point?.[1]??''}"></label></div><label>Notas<textarea name="notes">${esc(existing?.data.notes||'')}</textarea></label><p id="place-error" role="status"></p><button class="button primary">Guardar ${route?'marcador':'lugar'}</button></form>`);$('#place-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.target;if(saving)return;const p=[Number(form.lat.value),Number(form.lng.value)];if(!validPoint(p))return;const data={point:p,category:form.category.value,notes:form.notes.value},title=form.elements.title.value.trim();if(!title)return;if(route){draft.data.markers.push({id:crypto.randomUUID(),title,...data});stashDraft();showEditor();guideAdvance('marker');return;}if(!requireAccount())return;saving=true;try{await persist({...(existing||{}),id:existing?.id||crypto.randomUUID(),kind:'place',title,data});render();showPlaces();}catch(e){$('#place-error').textContent=errorText(e);}finally{saving=false;}};}
function allPlaces(){return [...active('place').map(e=>({...e.data,id:e.id,title:e.title})),...active('trip').flatMap(e=>(e.data.markers||[]).map(m=>({...m,routeId:e.id})))];}
function showPlaces(){guideAdvance('places');closeDialogs();content('Mis lugares',`<p class="muted">Tus accesos, aparcamientos y pequeños descubrimientos.</p><button class="button primary" data-action="new-place">＋ Añadir lugar</button><label>Buscar<input id="place-search" type="search" placeholder="Busca un rincón"></label><label>Categoría<select id="place-category"><option value="">Todas (${allPlaces().length})</option>${Object.entries(categories).map(([k,v])=>`<option value="${k}">${v} (${allPlaces().filter(m=>m.category===k).length})</option>`).join('')}</select></label><div id="place-list"></div>`);const list=()=>{const q=$('#place-search').value.toLowerCase(),cat=$('#place-category').value;$('#place-list').innerHTML=allPlaces().filter(m=>(!cat||m.category===cat)&&m.title.toLowerCase().includes(q)).map(m=>`<article class="route-summary" style="margin:10px 0"><span>${symbols[m.category]} ${esc(m.title)}<small class="muted"> · ${esc(categories[m.category])}</small></span><button class="text-button" data-action="${m.routeId?'route-place':'place-detail'}" data-id="${m.routeId||esc(m.id)}">Ver ficha ↗</button></article>`).join('')||'<p class="muted">No hay lugares que mostrar.</p>';};$('#place-search').oninput=list;$('#place-category').onchange=list;list();}
function placeDetail(id){const e=entries.find(e=>e.id===id);if(!e)return;content(e.title,`<span class="badge">${esc(categories[e.data.category])}</span><p>${number(e.data.point[0])}, ${number(e.data.point[1])}</p><p>${esc(e.data.notes||'Sin notas')}</p><button class="button primary" data-action="edit-place" data-id="${id}">Editar</button> <button class="text-button" data-action="windy-place" data-id="${id}">Abrir en Windy ↗</button> <button class="text-button danger" data-action="delete" data-id="${id}">Eliminar</button>`);}
function goalForm(){if(!requireAccount())return;closeDialogs();const year=new Date().getFullYear(),g=active('goal').find(e=>Number(e.data.year)===year);content('Un reto a tu medida',`<p>Cada aventura suma. Elige cuántos kilómetros te gustaría palear en ${year}.</p><form id="goal-form"><label>Objetivo anual (km)<input type="number" name="target" min="1" max="100000" step="1" value="${g?.data.target||100}" required></label><p id="goal-error" role="status"></p><button class="button primary">Guardar objetivo</button>${g?` <button class="text-button danger" type="button" data-action="delete" data-id="${g.id}">Eliminar objetivo</button>`:''}</form>`);$('#goal-form').onsubmit=async ev=>{ev.preventDefault();if(saving)return;saving=true;try{await persist({...(g||{}),id:g?.id||crypto.randomUUID(),kind:'goal',title:`Objetivo ${year}`,data:{year,target:Number(ev.target.elements.target.value)}});closeDialogs();render();toast('¡Reto preparado! Ahora, a disfrutar del camino.');}catch(e){$('#goal-error').textContent=errorText(e);}finally{saving=false;}};}
async function weather(){if(practice&&!draft?.data.points?.length){toast('Marca primero el punto de salida para consultar su tiempo.');return;}readFormIfOpen();if($('#map-wrap').classList.contains('fullscreen-map')){$('#map-wrap').classList.remove('fullscreen-map');const full=$('[data-map=fullscreen]');full.setAttribute('aria-pressed','false');full.setAttribute('aria-label','Pantalla completa');map?.invalidateSize();}closeDialogs();const point=draft?.data.points?.[0]||map?.getCenter()&&[map.getCenter().lat,map.getCenter().lng]||[39.98,4.08];content('Antes de salir al mar',`<p class="muted">Previsión para ${point.map(p=>p.toFixed(3)).join(', ')} · Centro del mapa o salida del borrador.</p><div id="weather-result" role="status">Consultando Open-Meteo…</div><p class="field-note">Consulta también avisos oficiales y condiciones locales. Una previsión no garantiza que sea seguro navegar.</p><a class="button secondary" href="https://www.windy.com/?${point[0]},${point[1]},12" target="_blank" rel="noopener">Abrir este punto en Windy ↗</a>`);if(practice){const card=$('.guide-card');if(card){$('#content-dialog').append(card);card.querySelector('h3').textContent='Consultando la previsión';const copy=card.querySelector('h3 + p');if(copy)copy.textContent='Espera el resultado. Puedes volver al paso anterior o salir de la guía.';positionGuide();}}const request=++weatherRequest;const controller=new AbortController();let timedOut=false;const timeout=setTimeout(()=>{timedOut=true;controller.abort();},15000);try{const response=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${point[0]}&longitude=${point[1]}&daily=temperature_2m_max,temperature_2m_min,wind_speed_10m_max,wind_gusts_10m_max&timezone=Europe%2FMadrid&forecast_days=5`,{signal:controller.signal});if(!response.ok)throw Error('El servicio meteorológico no está disponible.');const data=await response.json();if(request!==weatherRequest||!$('#weather-result'))return;const d=data.daily;if(!d?.time?.length||!Array.isArray(d.temperature_2m_min)||!Array.isArray(d.temperature_2m_max)||!Array.isArray(d.wind_speed_10m_max)||!Array.isArray(d.wind_gusts_10m_max))throw Error('La previsión no contiene datos.');$('#weather-result').innerHTML='<p class="field-note">Viento máximo diario y rachas en km/h. No incluye oleaje.</p>'+d.time.map((day,i)=>`<div class="weather-day"><strong>${esc(new Date(day+'T12:00:00').toLocaleDateString('es-ES',{weekday:'short',day:'numeric',month:'short'}))}</strong><span>☀ ${esc(d.temperature_2m_min[i]??'—')}–${esc(d.temperature_2m_max[i]??'—')} °C</span><span>↗ ${esc(d.wind_speed_10m_max[i]??'—')} km/h<br><small>Rachas ${esc(d.wind_gusts_10m_max[i]??'—')}</small></span></div>`).join('');guideAdvance('weather');}catch(e){if(request===weatherRequest&&$('#weather-result')){$('#weather-result').textContent=timedOut?'La previsión está tardando demasiado. Puedes reintentar o consultar este punto en Windy.':`No se pudo obtener la previsión. ${navigator.onLine?'Reintenta la consulta o abre este punto en Windy.':'Comprueba tu conexión a Internet.'}`;const retry=document.createElement('button');retry.type='button';retry.className='button secondary';retry.textContent='Reintentar previsión';retry.onclick=()=>weather();$('#weather-result').append(document.createElement('br'),retry);if(practice){const b=document.createElement('button');b.className='text-button';b.textContent='Continuar la práctica sin previsión';b.onclick=()=>guideAdvance('weather');$('#weather-result').append(b);}}}finally{clearTimeout(timeout);}}
async function showPhoto(path,name){content(name,'<p id="photo-status" role="status">Cargando fotografía privada…</p>');const token=++photoRequest;try{const url=path==='example'?'./guide-photo.svg':await signedPhoto(path);if(token!==photoRequest||!$('#photo-status'))return;const img=document.createElement('img');img.className='photo-view';img.alt=name;img.src=url;img.onerror=()=>{if($('#photo-status'))$('#photo-status').textContent='No se pudo cargar la fotografía. Vuelve a intentarlo.';};img.onload=()=>$('#photo-status')?.remove();$('#content-body').append(img);}catch(e){if(token===photoRequest&&$('#photo-status'))$('#photo-status').textContent=errorText(e);}}let photoRequest=0;
function showHelp(){content('Aprende paleando',`<p>Un mapa, tus recuerdos y muchas ganas de mar.</p><h3>Tu primera salida</h3><p>Pulsa Nueva salida, marca salida y llegada junto a la costa y revisa el trazado costero antes de guardar. Puedes importar un GPX para conservar un recorrido registrado.</p><button class="button primary" data-action="practice">Empezar práctica dirigida</button><p class="field-note">La práctica utiliza datos separados y una imagen de ejemplo. No se guarda en el servidor.</p><h3>Qué está disponible en esta edición</h3><p>Diario privado, dibujo manual, GPX, lugares, fotografías, objetivos y previsión. El trazado sigue la costa de la cartografía IDEIB/GOIB. El porcentaje de costa única sigue pendiente.</p><h3>Seguridad en el agua</h3><p>Consulta el viento, el estado del mar y los avisos. El mapa y las rutas dibujadas no garantizan navegabilidad.</p><h3>Versión 0.3.0</h3><p class="muted">28 acciones reales, práctica aislada, borradores por cuenta y fotografías privadas.</p>`);}
function preferences(){guideAdvance('preferences');if(!requireAccount())return;const p=active('preferences')[0];content('A tu manera',`<form id="preferences-form"><label class="checkbox-label"><input name="guide" type="checkbox" ${guideHidden()?'checked':''}> No mostrar de nuevo la guía al entrar</label><p class="muted">Unidades: kilómetros y minutos. Idioma: español.</p><p id="pref-message" role="status"></p><button class="button primary">Guardar preferencias</button></form>`);$('#preferences-form').onsubmit=async ev=>{ev.preventDefault();if(saving)return;saving=true;try{await persist({...(p||{}),id:p?.id||crypto.randomUUID(),kind:'preferences',title:'Preferencias',data:{...p?.data,hideGuide:ev.target.guide.checked}});try{localStorage.setItem(`paleando:guide:hidden:${user.id}`,String(ev.target.guide.checked));}catch{}closeDialogs();toast('Preferencias guardadas.');}catch(e){$('#pref-message').textContent=errorText(e);}finally{saving=false;}};}
