let guideFrame=0,guideTimer=0;
function guideHidden(){try{const saved=localStorage.getItem(`paleando:guide:hidden:${user?.id||'guest'}`);return saved===null?!!active('preferences')[0]?.data.hideGuide:saved==='true';}catch{return !!active('preferences')[0]?.data.hideGuide;}}
function offerLoginGuide(){if(!loginGuidePending||loading||saving||practice||!user||loadedAccount!==user.id)return;loginGuidePending=false;if(!guideHidden())startPractice();}
function startPractice(){if(practice)return;if(!map){toast('La práctica necesita el mapa. Comprueba la conexión y actualiza.');return;}if(saving||loading||undoEntry){toast('Termina la carga, guardado o recuperación en curso antes de empezar.');return;}readFormIfOpen();if(!stashDraft())return;practice={entries:structuredClone(entries),draft:structuredClone(draft),step:0,tab,checkpoints:[],filters:[$('#trip-search').value,$('#year-filter').value,$('#favorites-filter').checked]};entries=[];draft=null;$('#trip-search').value='';$('#year-filter').value='';$('#favorites-filter').checked=false;closeDialogs();$('#map-wrap').classList.remove('fullscreen-map');switchTab('mapa');document.body.classList.add('practice');$('#practice-banner').hidden=false;render();guideCheckpoint();guideRender();}
function guideCheckpoint(){if(!practice)return;practice.checkpoints[practice.step]={entries:structuredClone(entries),draft:structuredClone(draft),mode,tab,dialog:$('dialog[open]')?.id,point:practice.markerPoint,undo:structuredClone(undoEntry)};}
function practiceGuard(ev){if(!practice)return;const s=guideSteps[practice.step];if(!s)return;if(ev.target.closest('.guide-card,#exit-practice,#practice-finish'))return;if(s.event==='weather'&&ev.target.closest('#weather-result button'))return;const target=$(s.target);if(s.target==='#save-entry'&&ev.target.closest('#discard-draft,#edit-track,#add-route-marker,#editor-import,#close-editor,[data-remove-marker],[data-remove-photo],[data-photo]')){ev.preventDefault();ev.stopImmediatePropagation();return;}if(target?.contains(ev.target)||ev.target===target||ev.target.closest('label')?.contains(target))return;if(s.target==='#save-entry'&&ev.target.closest('#entry-form input,#entry-form textarea,#entry-form select'))return;if(s.target==='#place-form button'&&ev.target.closest('#place-form input,#place-form textarea,#place-form select'))return;if(ev.type==='submit'&&ev.target===target?.closest('form'))return;if(ev.type==='keydown'&&['Tab','Shift'].includes(ev.key))return;ev.preventDefault();ev.stopImmediatePropagation();if(ev.type==='click')toast('Completa la acción destacada o sal de la guía.');}
function positionGuide(){const card=$('.guide-card'),s=practice&&guideSteps[practice.step],target=s&&$(s.target);if(!card||!target)return;const vv=window.visualViewport,W=vv?.width||innerWidth,H=vv?.height||innerHeight,offset=vv?.offsetTop||0,r=target.getBoundingClientRect();const h=card.getBoundingClientRect().height,w=Math.min(350,W-24),left=Math.max(12,Math.min(r.left,W-w-12));card.style.width=w+'px';card.style.left=left+'px';card.style.right='auto';card.style.bottom='auto';const below=r.bottom+12,above=r.top-h-12;card.style.top=(below+h<H+offset-12?below:above>offset+48?above:Math.max(offset+50,H+offset-h-12))+'px';}
function guideRender(){if(!practice)return;cancelAnimationFrame(guideFrame);$$('.guide-highlight').forEach(e=>e.classList.remove('guide-highlight'));$('.guide-card')?.remove();const s=guideSteps[practice.step];if(!s){finishPractice();return;}const target=$(s.target);target?.classList.add('guide-highlight');target?.scrollIntoView({block:'center',behavior:'instant'});const card=document.createElement('aside');card.className='guide-card';card.setAttribute('role','region');card.setAttribute('aria-label','Guía interactiva');card.innerHTML=`<p class="eyebrow">PRÁCTICA ${practice.step+1} / ${guideSteps.length}</p><progress max="${guideSteps.length}" value="${practice.step+1}" aria-label="Progreso de la guía"></progress><h3>${s.title}</h3><p>${s.text}</p><label class="checkbox-label"><input id="guide-hide" type="checkbox" ${guideHidden()?'checked':''}> No mostrar de nuevo</label><div class="actions"><button class="text-button" id="guide-back" ${practice.step?'':'disabled'}>Volver al paso anterior</button><button class="text-button" id="guide-exit">Salir de la guía</button></div>`;($('dialog[open]')||document.body).append(card);$('#guide-exit').onclick=()=>endPractice();$('#guide-back').onclick=guideBack;$('#guide-hide').onchange=ev=>{practice.hideChoice=ev.target.checked;try{localStorage.setItem(`paleando:guide:hidden:${user?.id||'guest'}`,String(ev.target.checked));}catch{toast('No se pudo recordar la preferencia en este navegador.');}};guideFrame=requestAnimationFrame(positionGuide);}
function guideAdvance(event){if(!practice||guideSteps[practice.step]?.event!==event)return;practice.step++;clearTimeout(guideTimer);guideTimer=setTimeout(()=>{guideCheckpoint();guideRender();},50);}
function guideBack(){if(!practice||!practice.step)return;clearTimeout(guideTimer);const c=practice.checkpoints[--practice.step];closeDialogs();entries=structuredClone(c.entries);draft=structuredClone(c.draft);undoEntry=structuredClone(c.undo);mode=c.mode;practice.markerPoint=c.point;clearTimeout(undoTimer);switchTab(c.tab);render();$('#draw-bar').hidden=!mode;$('#map-hint').hidden=!mode;$('#finish-draw').hidden=mode==='marker';$('#remove-point').hidden=mode==='marker';$('#draw-label').textContent=mode==='marker'?'Toca dónde añadir el marcador':`${draft?.data.points.length||0} puntos · Revisa el recorrido`;if(c.dialog==='editor-dialog')showEditor();else if(c.dialog==='place-form'||c.dialog==='content-dialog'&&guideSteps[practice.step].event==='marker')markerForm(c.point,true);else if(c.dialog==='menu-dialog')openDialog('#menu-dialog');else if(c.dialog==='content-dialog'){const previous=guideSteps[practice.step-1]?.event;if(previous==='places')showPlaces();else if(previous==='plans')showPlans();else if(previous==='preferences')preferences();else if(previous==='weather')weather();else {const e=entries.find(visible);if(e)detail(e.id);}}guideRender();}
function finishPractice(){if(!practice)return;closeDialogs();$('.guide-card')?.remove();$$('.guide-highlight').forEach(e=>e.classList.remove('guide-highlight'));content('Ya sabes cómo empezar',`<section id="practice-finish"><p class="badge">PRÁCTICA COMPLETADA</p><h3>Has creado, guardado, editado y recuperado una salida.</h3><p>Tu diario y tus estadísticas reales siguen intactos.</p><button id="practice-discard" class="button secondary">Descartar práctica</button> <button id="practice-convert" class="button primary" ${practice.draft?'disabled':''}>Convertir en una salida real</button>${practice.draft?'<p>Tu borrador anterior se conservará. Descarta la práctica para recuperarlo.</p>':'<p>Revisarás la fecha, el trazado y los datos antes de guardar. La imagen de ejemplo se eliminará.</p>'}</section>`);$('#practice-discard').onclick=()=>endPractice(true);$('#practice-convert').onclick=()=>{const sample=entries.find(e=>e.kind==='trip'&&visible(e));if(!sample)return;const data=structuredClone(sample.data);data.photos=[];data.markers.forEach(m=>delete m.photoId);data.date=today();endPractice(true);if(!requireAccount())return;draft={id:crypto.randomUUID(),kind:'trip',title:sample.title,data};stashDraft();showEditor();$('#editor-message').textContent='Revisa fecha, trazado y datos. Pulsa Guardar salida solo si corresponden a una salida real.';};}
function endPractice(done=false){if(!practice)return;const prior=practice;clearTimeout(guideTimer);cancelAnimationFrame(guideFrame);practice=null;entries=prior.entries;draft=prior.draft;clearTimeout(undoTimer);undoEntry=null;$('#toast').hidden=true;closeDialogs();$('.guide-card')?.remove();$$('.guide-highlight').forEach(e=>e.classList.remove('guide-highlight'));document.body.classList.remove('practice');$('#practice-banner').hidden=true;mode=null;$('#draw-bar').hidden=true;$('#map-hint').hidden=true;$('#trip-search').value=prior.filters[0];$('#favorites-filter').checked=prior.filters[2];render();$('#year-filter').value=prior.filters[1];switchTab(prior.tab);render();stashDraft();toast(done?'Práctica terminada. Tu diario real está intacto.':'Tu diario y borrador originales están restaurados.');}
window.addEventListener('resize',positionGuide);window.addEventListener('scroll',positionGuide,true);window.visualViewport?.addEventListener('resize',positionGuide);
function bind(){for(const event of ['click','pointerdown','keydown','submit','change'])document.addEventListener(event,practiceGuard,true);for(const d of $$('dialog'))d.addEventListener('cancel',ev=>{if(practice)ev.preventDefault();}); $$('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$$('[data-close]').forEach(b=>b.onclick=()=>{b.closest('dialog').close();guideAdvance('content-close');$('#menu-button').setAttribute('aria-expanded','false');});$('#menu-button').onclick=()=>{$('#continue-draft').hidden=!draft;openDialog('#menu-dialog');$('#menu-button').setAttribute('aria-expanded','true');guideAdvance('menu');};$('#account-button').onclick=account;$('#resume-draft').onclick=()=>{showEditor();guideAdvance('resume');};$('#new-button').onclick=()=>{newEntry();guideAdvance('new');};$('#plan-button').onclick=()=>newEntry('plan');$('#diary-new').onclick=()=>newEntry();$('#weather-button').onclick=weather;$('#goal-button').onclick=coastInfo;$('#guide-button').onclick=showHelp;$('#refresh').onclick=()=>{if(practice)return;if(user)sync();else{initMapIfNeeded();toast('El mapa está listo. Entra para cargar tu diario.');}};$$('[data-map]').forEach(b=>b.onclick=()=>mapAction(b));$$('[name=base]').forEach(i=>i.onchange=()=>setBase(i.value));$$('[data-layer]').forEach(i=>i.onchange=()=>{if(!map)return;const g=groups[i.dataset.layer];if(i.checked)g.addTo(map);else map.removeLayer(g);});$('#close-editor').onclick=()=>{readForm();if(stashDraft()){$('#editor-dialog').close();guideAdvance('editor-close');}};$('#editor-dialog').addEventListener('cancel',ev=>{readForm();if(!stashDraft())ev.preventDefault();});$('#entry-form').oninput=()=>{readForm();if(draft)$('#route-summary').textContent=`${number(tripKm(draft.data))} km · ${draft.data.points.length} puntos${draft.data.source==='coastal'?' · siguiendo la costa':''}`;};$('[name=roundtrip]').onchange=()=>{readForm();renderDraft();if(draft.data.roundtrip)guideAdvance('roundtrip');};$('#edit-track').onclick=()=>{readForm();beginDraw();};$('#add-route-marker').onclick=()=>{readForm();beginDraw(true);};$('#finish-draw').onclick=()=>{if(draft.data.points.length<2){toast('Selecciona al menos salida y llegada.');return;}showEditor();guideAdvance('review');};$('#remove-point').onclick=()=>{try{if(draft.data.source==='coastal')draft.data=removeCoastalPoint(draft.data);else draft.data.points.pop();stashDraft();drawDraft();$('#draw-label').textContent=`${number(tripKm(draft.data))} km · ${(draft.data.anchors||draft.data.points).length} puntos marcados`;}catch(error){toast(errorText(error));}};$('#cancel-draw').onclick=showEditor;$('#discard-draft').onclick=()=>{if(confirm('¿Descartar este borrador? Los cambios sin guardar se perderán.')){draft=null;stashDraft();drawDraft();$('#editor-dialog').close();if(importQueue.length)nextImport();}};$('#entry-form').onsubmit=saveDraft;$('#undo').onclick=undo;$('#trip-search').oninput=renderDiary;$('#year-filter').onchange=renderDiary;$('#favorites-filter').onchange=renderDiary;$('#auth-form').onsubmit=e=>{e.preventDefault();authenticate(false);};$('#signup').onclick=()=>authenticate(true);$('#logout').onclick=logout;$('#photo-input').onchange=addPhotos;$('#photo-input').addEventListener('click',ev=>{if(practice){ev.preventDefault();addPhotos(ev);}});$('#editor-import').onclick=()=>{readForm();importQueue=[];$('#gpx-input').multiple=false;$('#gpx-input').click();};$('#gpx-input').onchange=importFiles;$('#exit-practice').onclick=()=>endPractice();document.addEventListener('click',delegated);document.addEventListener('change',e=>{const id=e.target.dataset.markerPhoto;if(id&&draft){const marker=draft.data.markers.find(m=>m.id===id);if(marker){marker.photoId=e.target.value;stashDraft();if(marker.photoId)guideAdvance('associate');}}});window.addEventListener('beforeunload',ev=>{if(saving){ev.preventDefault();ev.returnValue='';}if(draft&&!practice)stashDraft();});window.addEventListener('offline',()=>{state('Sin conexión · conserva el borrador');});window.addEventListener('online',()=>{state('Conexión recuperada · pulsa Actualizar');});document.addEventListener('visibilitychange',()=>{if(document.hidden&&draft&&!practice){readFormIfOpen();stashDraft();}});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!$('#layers').hidden){$('#layers').hidden=true;$('[data-map=layers]').setAttribute('aria-expanded','false');}});}
function initMapIfNeeded(){if(!map)initMap();}
async function mapAction(button){const action=button.dataset.map;if(action==='layers'){$('#layers').hidden=!$('#layers').hidden;button.setAttribute('aria-expanded',!$('#layers').hidden);return;}if(!map){toast('El mapa aún no está disponible. Comprueba la conexión.');return;}if(action!=='layers'){$('#layers').hidden=true;$('[data-map=layers]').setAttribute('aria-expanded','false');}if(action==='island'){map.fitBounds([[39.80,3.78],[40.10,4.36]],{padding:[25,25]});return;}if(action==='fullscreen'){$('#map-wrap').classList.toggle('fullscreen-map');button.setAttribute('aria-pressed',String($('#map-wrap').classList.contains('fullscreen-map')));button.setAttribute('aria-label',$('#map-wrap').classList.contains('fullscreen-map')?'Restaurar mapa':'Pantalla completa');setTimeout(()=>map.invalidateSize(),100);return;}if(action==='location'){if(!navigator.geolocation){toast('Tu navegador no permite localizar el dispositivo.');return;}button.disabled=true;toast('Solicitando permiso de ubicación…');navigator.geolocation.getCurrentPosition(p=>{locationLayer.clearLayers();const ll=[p.coords.latitude,p.coords.longitude];L.circle(ll,{radius:p.coords.accuracy,color:'#11796f',fillOpacity:.12}).addTo(locationLayer);L.circleMarker(ll,{radius:7,color:'white',weight:3,fillColor:'#11796f',fillOpacity:1}).addTo(locationLayer).bindPopup(`Tu ubicación · precisión ±${Math.round(p.coords.accuracy)} m`).openPopup();map.setView(ll,15);button.disabled=false;},e=>{button.disabled=false;toast(e.code===1?'Permiso GPS denegado. Puedes habilitarlo en los ajustes del navegador.':e.code===3?'El GPS tardó demasiado. Vuelve a intentarlo.':'No se pudo obtener tu ubicación.');},{enableHighAccuracy:true,timeout:15000,maximumAge:10000});}}
async function saveDraft(ev){ev.preventDefault();if(saving||!draft)return;readForm();const ownerEpoch=accountEpoch;if(practice&&guideSteps[practice.step]?.event==='save'&&practice.step===24&&practice.beforeEdit===JSON.stringify(draft)){$('#editor-message').textContent='Cambia el nombre o las notas antes de guardar.';return;}if(!draft.title.trim()||draft.data.points.length<2){$('#editor-message').textContent='Añade un nombre y al menos dos puntos de recorrido.';return;}saving=true;$('#save-entry').disabled=true;try{validateEntry(draft);await persist({...draft,title:draft.title.trim()});if(ownerEpoch!==accountEpoch)return;draft=null;stashDraft();closeDialogs();render();switchTab('diario');toast(practice?'Guardado solo en la práctica.':'¡Otra aventura en tu cuaderno de mar!');guideAdvance('save');if(importQueue.length)nextImport();}catch(e){if(ownerEpoch===accountEpoch)$('#editor-message').textContent=errorText(e);}finally{saving=false;$('#save-entry').disabled=false;}}
async function addPhotos(ev){if(practice){draft.data.photos.push({id:crypto.randomUUID(),path:'example',name:'Fotografía de práctica'});renderDraft();guideAdvance('photo');return;}if(!draft||!requireAccount())return;if(saving)return;const targetDraft=draft,owner=user.id,epoch=accountEpoch;saving=true;$('#save-entry').disabled=true;try{for(const file of ev.target.files){const photo=await uploadPhoto(file,owner);if(epoch!==accountEpoch||draft!==targetDraft)throw Error('La sesión ha cambiado. La fotografía no se ha asociado a otra cuenta.');draft.data.photos.push(photo);stashDraft();}renderDraft();state('Fotos subidas · ficha pendiente de guardar');}catch(e){$('#editor-message').textContent=errorText(e);renderDraft();}finally{saving=false;$('#save-entry').disabled=false;ev.target.value='';}}
async function importFiles(ev){const files=[...ev.target.files];ev.target.value='';if(!requireAccount()||!files.length)return;try{if(draft){if(files.some(f=>f.size>10*1024*1024))throw Error('Cada GPX debe ocupar menos de 10 MB.');if(files.length>1)throw Error('Importa un solo GPX dentro de una ficha.');if(draft.data.points.length&&!confirm('¿Sustituir el trazado del borrador por este GPX?'))return;const parsed=parseGPX(await files[0].text());draft.data={...draft.data,...parsed};if(!draft.title)draft.title=parsed.title;stashDraft();showEditor();return;}const parsedFiles=[];for(const file of files){if(file.size>10*1024*1024)throw Error('Cada GPX debe ocupar menos de 10 MB.');parsedFiles.push(parseGPX(await file.text()));}importQueue=parsedFiles;nextImport();}catch(e){toast(errorText(e));}}
function nextImport(){if(!importQueue.length)return;const p=importQueue.shift();draft={id:crypto.randomUUID(),kind:'trip',title:p.title,data:{...p,date:today(),markers:[],photos:[]}};stashDraft();showEditor();toast(`Revisa el GPX antes de guardar.${importQueue.length?` Quedan ${importQueue.length} por revisar.`:''}`);}
async function authenticate(signup){const form=$('#auth-form');const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);$('#auth-message').textContent=signup?'Creando tu cuenta…':'Entrando…';try{const c=await getClient();const credentials={email:form.email.value.trim(),password:form.password.value};if(!form.reportValidity()){ $('#auth-message').textContent='Revisa el correo y la contraseña.';return;}const {data,error}=await (signup?c.auth.signUp({...credentials,options:{emailRedirectTo:location.origin+location.pathname}}):c.auth.signInWithPassword(credentials));if(error)throw error;form.password.value='';if(!data.session){$('#auth-message').textContent='Revisa tu correo y confirma la cuenta antes de entrar.';return;}closeDialogs();loginGuidePending=true;setTimeout(offerLoginGuide,250);}catch(e){$('#auth-message').textContent=errorText(e);}finally{buttons.forEach(b=>b.disabled=false);}}
function account(){if(!user){openDialog('#auth-dialog');return;}content('Tu cuenta',`<p>${esc(user.email)}</p><p class="muted">Diario privado en el nuevo proyecto Paleando Menorca.</p><button class="button secondary" data-action="sync">Actualizar mi diario</button> <button class="text-button" data-action="logout">Cerrar sesión</button>`);}
async function logout(){if(saving||practice){toast('Termina el guardado o sal de la práctica antes de cerrar sesión.');return;}if(draft&&!stashDraft())return;try{const c=await getClient();const {error}=await c.auth.signOut();if(error)throw error;closeDialogs();toast('Sesión cerrada. Tu diario sigue en tu cuenta.');}catch(e){toast(errorText(e));}}
async function delegated(ev){const photo=ev.target.closest('[data-photo]');if(photo){showPhoto(photo.dataset.photo,photo.dataset.photoName);return;}const rm=ev.target.closest('[data-remove-marker],[data-remove-photo]');if(rm&&draft){const key=rm.dataset.removeMarker?'markers':'photos',id=rm.dataset.removeMarker||rm.dataset.removePhoto;const old=structuredClone(draft.data);if(key==='photos'&&!confirm('¿Quitar esta foto de la galería de la salida y de sus marcadores? No se borrará del almacenamiento.'))return;draft.data[key]=draft.data[key].filter(x=>x.id!==id);if(key==='photos')draft.data.markers.forEach(m=>{if(m.photoId===id)delete m.photoId;});stashDraft();renderDraft();const b=document.createElement('button');b.type='button';b.className='text-button';b.textContent='↩ Recuperar lo que acabas de quitar';b.onclick=()=>{draft.data=old;stashDraft();renderDraft();b.remove();};$('#draft-'+(key==='photos'?'photos':'markers')).append(b);return;}const menu=ev.target.closest('[data-menu]');if(menu){const what=menu.dataset.menu;closeDialogs();({draft:showEditor,places:showPlaces,plans:showPlans,import:()=>{if(!requireAccount())return;$('#gpx-input').multiple=true;$('#gpx-input').click();},preferences,help:showHelp,account}[what])?.();return;}const b=ev.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,e=entries.find(x=>x.id===id);switch(b.dataset.action){case'new':newEntry();break;case'plan':newEntry('plan');break;case'detail':case'route-place':detail(id);break;case'edit':edit(id);break;case'delete':await deleteEntry(id);break;case'goal':goalForm();break;case'coast-info':coastInfo();break;case'new-place':if(requireAccount())markerForm();break;case'place-detail':placeDetail(id);break;case'edit-place':if(draft){toast('Resuelve el borrador antes de editar lugares.');break;}markerForm(e.data.point,false,e);break;case'windy-place':window.open(`https://www.windy.com/?${e.data.point[0]},${e.data.point[1]},14`,'_blank','noopener');break;case'locate':closeDialogs();switchTab('mapa');if(map)map.fitBounds(e.data.points,{padding:[45,45]});break;case'export':{const url=URL.createObjectURL(new Blob([exportGPX(e)],{type:'application/gpx+xml'}));const a=document.createElement('a');a.href=url;a.download=`paleando-${e.id}.gpx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'complete':if(draft){toast('Resuelve el borrador antes de registrar la ruta como realizada.');break;}draft={id:crypto.randomUUID(),kind:'trip',title:e.title,data:{...structuredClone(e.data),date:today(),fromPlan:e.id}};stashDraft();showEditor();toast('Revisa la fecha y los datos antes de guardar como salida realizada.');break;case'practice':startPractice();break;case'sync':closeDialogs();sync();break;case'logout':logout();break;case'marker-photo':{const m=e.data.markers.find(m=>m.id===b.dataset.marker);const p=e.data.photos.find(p=>p.id===m.photoId);if(p)showPhoto(p.path,p.name);break;}}}
async function boot(){bind();initMap();recoverDraft();render();try{const c=await getClient();const {data,error}=await c.auth.getSession();if(error)throw error;user=data.session?.user||null;recoverDraft();if(user)await sync();c.auth.onAuthStateChange((event,session)=>{const next=session?.user||null;if(user?.id===next?.id)return;if(practice)endPractice();if(draft)stashDraft();accountEpoch++;syncVersion++;loadedAccount=null;loading=false;clearTimeout(undoTimer);undoEntry=null;importQueue=[];weatherRequest++;photoRequest++;closeDialogs();mode=null;$('#draw-bar').hidden=true;$('#map-hint').hidden=true;user=next;entries=[];draft=null;recoverDraft();render();if(user)setTimeout(async()=>{await sync();offerLoginGuide();},0);else state('Sin iniciar sesión · v0.3.0');});render();}catch(e){state('Conexión de cuenta no disponible');toast('No se pudo conectar con la cuenta. El mapa sigue disponible. Recarga para reintentar.');}}
boot();

function readFormIfOpen(){if($('#editor-dialog').open)readForm();}

async function hydratePhotos(root){for(const button of root.querySelectorAll('[data-photo]')){const path=button.dataset.photo;const image=document.createElement('img');image.alt=button.dataset.photoName||'Fotografía';image.loading='lazy';button.prepend(image);try{const url=path==='example'?'./guide-photo.svg':await signedPhoto(path);if(!button.isConnected)continue;image.src=url;image.onerror=()=>{image.remove();button.title='No se pudo cargar la vista previa. Pulsa para reintentar.';};}catch{image.remove();button.title='Vista previa no disponible. Pulsa para reintentar.';}}}
